//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Mechanical Filter Data - HYDAC
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
// REQ: 			HYDAC filter system - ModbusTCP option                                                                                                                                                                                                                                                                                                                          
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-07-14		William Veim			Initial release              
//
//===============================================================================================================================

 (*************************************************************************
 *	CONGIURING MODBUS REQUEST
 *************************************************************************)
 
MTCP_Request[0].Enable :=									TRUE;
MTCP_Request[0].NodeAdr := 							1;
MTCP_Request[0].FunctionCode := 					eFun#Fn04_ReadInputRegisters;
MTCP_Request[0].Read.StartAddressLocal :=		0;
MTCP_Request[0].Read.StartAddressRemote := 	3001;
MTCP_Request[0].Read.Count := 						5;

MTCP_Request[1].Enable :=									TRUE;
MTCP_Request[1].NodeAdr := 							1;
MTCP_Request[1].FunctionCode := 					eFun#Fn16_WriteMultipleRegisters;
MTCP_Request[1].Write.StartAddressLocal := 	 5;
MTCP_Request[1].Write.StartAddressRemote :=  3000;
MTCP_Request[1].Write.Count := 						  1; 

FB_MTCP(Enable:=						TRUE, 
				IPAddress:=					Cfg_IPAdr, 
				PortNo:=						Cfg_PortNo, 
				UpdateRate:=				Cfg_UpdateRate, 
				NodeTimeOut:=			ADD_TIME(In1:=Cfg_UpdateRate, In2:=Cfg_UpdateRate), 
				Status=>						MTCP_Status, 
				RequestCycleDone=>	MTCP_ReqCycleDone, 
				RequestCycleTime=>	MTCP_ReqCycleTime, 
				Error=>						MTCP_Error, 
				ErrorID=>					MTCP_ErrorID, 
				ErrorIDEx=>					MTCP_ErrorID_Ex, 
				ErrorRequestNO=>		MTCP_ErrorRequestNO, 
				ModbusError=>			MTCP_ModbusError, 
				Requests:=					MTCP_Request, 
				Coils:=							MTCP_Coils, 
				DiscreteInputs:=			MTCP_DiscreteInputs, 
				InputRegisters:=			MTCP_InputRegister, 
				HoldingRegisters:=		MTCP_HoldingRegister);

(*************************************************************************
 *	INTERNAL VARIABLE CONTROL
 *************************************************************************)
 
Ext_MechanicalFilter_Data.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

FB_Watchdog(ENS:=TRUE, 
						Cfg_Type:=1,
						Inp_Bool:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=14));

//Communication state
IF MTCP_Request[0].Status.Success AND NOT MTCP_Request[0].Status.Error 
	AND MTCP_Request[1].Status.Success AND NOT MTCP_Request[1].Status.Error 
	AND NOT FB_Watchdog.Sts_Timeout THEN
	
	Wrk_CommState:=TRUE;
ELSE
	Wrk_CommState:=FALSE;
END_IF;

(*************************************************************************
 *	UPDATING VARIABELS
 *************************************************************************)

IF NOT Wrk_CommState THEN
	Ext_MechanicalFilter_Data.EXT_Operator.Actual_State:= 'Communication fault';
ELSIF TestABitN(In:=MTCP_HoldingRegister[0], Pos:=0) THEN
	Ext_MechanicalFilter_Data.EXT_Operator.Actual_State:= 'Standby';
ELSIF TestABit(In:=MTCP_HoldingRegister[0], Pos:=0) THEN
	Ext_MechanicalFilter_Data.EXT_Operator.Actual_State:= 'Flushing ongoing';
END_IF;

//Input data
Ext_MechanicalFilter_Data.EXT_Operator.FlushingStarted:= 			TestABit(In:=MTCP_HoldingRegister[0], Pos:=0);
Ext_MechanicalFilter_Data.EXT_Operator.InletPressure:=			  	HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[1], UnvalidValue:=16#FFFF) / 100; 	// bar
Ext_MechanicalFilter_Data.EXT_Operator.OutletPressure:=			HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[2], UnvalidValue:=16#FFFF) / 100; 	// bar
Ext_MechanicalFilter_Data.EXT_Operator.DifferencialPressure:= 	HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[3], UnvalidValue:=16#FFFF) / 100; 	// bar

//Output data
OutABit(InOut:=MTCP_HoldingRegister[5], Pos:=0, BitVal:=Ext_MechanicalFilter_Data.EXT_Operator.StartFlushing); //Remote start
OutABit(InOut:=MTCP_HoldingRegister[5], Pos:=2, BitVal:=Ext_MechanicalFilter_Data.EXT_Operator.ResetFault); //Fault acknowledge
OutABit(InOut:=MTCP_HoldingRegister[5], Pos:=1, BitVal:=FALSE); //Lock backflush

(*************************************************************************
 *	STATISTICS
 *************************************************************************)
 
Ext_MechanicalFilter_Data.EXT_Statistics.Total_Today:=			0;
Ext_MechanicalFilter_Data.EXT_Statistics.Total_Yesterday:=	0;
Ext_MechanicalFilter_Data.EXT_Statistics.Total_Week:=			0;	
Ext_MechanicalFilter_Data.EXT_Statistics.Total_Month:=			0;
Ext_MechanicalFilter_Data.EXT_Statistics.Total_Year:=				0;
Ext_MechanicalFilter_Data.EXT_Statistics.Total:=						0;

(*************************************************************************
 *	ALARM/FAULT STATUS
 *************************************************************************)

Wrk_State[1]:=NOT Wrk_CommState;
Wrk_Suffix[1]:='Communication fault';
Wrk_State[2]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=1);
Wrk_Suffix[2]:='Common alarm';
Wrk_State[3]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=2);
Wrk_Suffix[3]:='Motor protection';
Wrk_State[4]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=3);
Wrk_Suffix[4]:='Motor plug';
Wrk_State[5]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=4);
Wrk_Suffix[5]:='Pump fault';
Wrk_State[6]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=5);
Wrk_Suffix[6]:='Inlet pressure sensor fault';
Wrk_State[7]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=6);
Wrk_Suffix[7]:='Outlet pressure sensor fault';
Wrk_State[8]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=7);
Wrk_Suffix[8]:='High differential pressure';
Wrk_State[9]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=8);
Wrk_Suffix[9]:='Fault proximity switch';
Wrk_State[10]:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=11);
Wrk_Suffix[10]:='Service';
Wrk_State[11]:=FALSE;
Wrk_Suffix[11]:='';
Wrk_State[12]:=FALSE;
Wrk_Suffix[12]:='';

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)

FB_Data_Logic(Ext_Alarm:=						Ext_MechanicalFilter_Data.EXT_Alarm, 
						EXT_Engineering:=			Ext_MechanicalFilter_Data.EXT_Engineering, 
						Ext_General:=					Ext_MechanicalFilter_Data.EXT_General, 
						Int_Alarm:=						Int_Alarm, 
						Inp_StateState:=				Wrk_State, 
						Inp_StateSuffix:=				Wrk_Suffix, 
						Inp_AlmSuppressDesc:=	Cfg_AlmSuppressDesc, 
						Inp_AlmSuppress:=			Inp_AlmSuppress);

(*************************************************************************
 *	UPDATING OUTPUT
 *************************************************************************)
 
 //BLOCK
 Sts_Alarm:= FB_Data_Logic.Sts_AlarmTriggered;
 
 //STRUCTURE
 Ext_MechanicalFilter_Data.EXT_General.Connected_ControlCabinet:=	Cfg_ConnCab;
 Ext_MechanicalFilter_Data.EXT_General.Controlled_FromController:=	Cfg_ControllerName;
 Ext_MechanicalFilter_Data.EXT_General.Process_TAG:=							Cfg_ProcessTAG;
